// Each week includes reading, guided execution and time to revise an unsuccessful attempt.
const activities={
 1:['修改预测程序：分别改变输入、w 和公式，抄下三组输出。','手算一次梯度更新；对比学习率 0.01、0.1、1，再做梯度练习。','用独立输入比较模型与常数基线；建立第一份实验手记。','检查模型、参数、损失、更新和评测五项；不会的返回本周课文。'],
 2:['完成字符编码与还原；写出输入数组、向量和参数表的形状。','计算一组注意力权重；故意破坏掩码，再完成因果 mask 练习。','将短句展开成每个位置的输入与目标；画训练与生成的两条流程。','解释 Transformer 的模块、因果约束和生成顺序，复习错误题。'],
 3:['检查 tiny_lm.py 的 corpus、编码与目标右移；制作数据卡。','完成稳定交叉熵练习；在 CPU 上跑 40 步微型语言模型。','固定数据和预算，只改变学习率；保存两次命令、日志和验证结果。','检查保存字段和恢复限制，整理第一份语言模型实验报告。'],
 4:['复现“没更新”和“学习率过大”两种故障，给出不同证据。','完成加权累积练习；记录 batch、序列长度与一次更新的预算。','选择一个指标和基准，写出协议；为失败样例建立分类。','完成第 1–4 周阶段检查，补做未能解释的数值与代码。'],
 5:['制作十条指令示范，逐位置标记回答边界和 loss mask。','手算 LoRA 更新矩阵，完成代码练习和 rank 参数预算实验。','画 SFT、候选重排序和偏好优化三条流程；写全量与 LoRA 的对照设计。','比较 SFT 与 LoRA 的职责，核对 PT、rewardx 等待确认术语。'],
 6:['用给定分辨率计算视觉位置数，画视觉塔与连接层的形状图。','列举图文错配与表示塌缩的检查，设计一个冻结表示的任务评测。','为 codec 单独设计重建评测，再画编码、预测和解码接口。','检查视觉特征、可解码 latent 与动作所需信息的区别。'],
 7:['手算一个加噪样本，分别画训练与多步采样的流程。','运行已知速度的积分示例，使用路径演示并标明其并非训练结果。','制定十个提示的图像对比协议，记录采样预算与盲评规则。','解释结构、目标、采样器和评价指标四个维度，整理误区。'],
 8:['检查 tiny_world_model.py 的状态、动作与下一状态时间关系。','画 JEPA 上下文、预测器、目标分支；说明停止梯度与塌缩风险。','在 CPU 上训练微型世界模型；完成 rollout 练习并保存动作打乱对照。','完成第 1–8 周阶段检查；交付按 horizon 展开的基线报告。'],
 9:['读 KDA 架构资料，写出状态形状、写入与读取三个待验证问题。','完成记忆边界练习，把 reset、detach、optimizer.step 画在不同线上。','在 OmniFM 中追踪入口、配置、batch、loss 和更新；记录证据等级。','交付训练接口表与状态边界图；未知运行配置明确标注。'],
 10:['运行最小行为克隆示例，在多个初始位置做闭环测试。','定义动作维度、单位和坐标系；画 action chunk 的预测执行时序。','比较规则策略、学到策略与模型选择的玩具闭环；固定成功标准。','画具身系统的职责图，分析世界模型和策略各自的失败。'],
 11:['从基线选择一个具体失败，写输入噪声假设与否定条件。','设计基线和变体的种子矩阵，核对样本量、有效目标和计算预算。','执行允许范围内的小规模受控实验；保存全部结果和失败样例。','整理事实、解释、限制和下一步，导出可复查的实验报告。'],
 12:['在新输出目录按 README 复现最小配置，记录隐藏依赖。','做一次十分钟答辩，回答模型选择、训练排错和评测追问。','整理世界模型作品；为古琴重启写数据、基线、指标和预算。','完成综合复习，以代码与实验记录标记能力层级，规划后续实践。']
};
const deliverables={
 1:'一份模型身份卡、一次手算与代码更新、独立评测记录。',
 2:'编码往返检查、因果掩码实现、训练与生成的信息流图。',
 3:'CPU 微型语言模型基线、学习率对照、数据卡与存档审查。',
 4:'故障修复记录、加权累积实现、评测协议与第一阶段复盘。',
 5:'指令示范与 mask 审查、LoRA 数值实现、适配和偏好流程对照设计。',
 6:'视觉前向形状图、图文监督分析、独立 codec 重建评测方案。',
 7:'加噪与速度数值实验、训练/采样流程图、图像评价协议。',
 8:'训练后的动作条件世界模型、按 horizon 的评测和动作对照。',
 9:'OmniFM 入口与配置地图、一次更新时序、状态边界审查。',
 10:'最小行为克隆代码、闭环对照结果、VLA 与动作接口图。',
 11:'受控实验的基线、变体、重复结果、失败分析和结论边界。',
 12:'可复现作品、实际项目答辩、能力清单与古琴重启方案。'
};
export function enrichWeek(w,lessons){
 const ls=lessons.filter(l=>l.week===w.id),extra=activities[w.id];
 const minutes=w.hours===10?[60,90,60,90,60,120,120]:[90,120,90,120,90,120,90];
 const schedule=[
  {title:ls[0].title,action:'先读本课新词，再沿编号步骤阅读。手算例子之后运行代码，对照预期输出。',expected:'用自己的例子解释本课输入、输出和新概念。',lessonId:ls[0].id},
  {title:'第一次引导练习',action:extra[0],expected:ls[0].guidedPractice.steps.at(-1).expected,lessonId:ls[0].id},
  {title:ls[1].title,action:'先检查前置课程，再学新词和数值推演。检查题允许先看提示，再对照解析。',expected:'能够解释本课算例每一步为什么这样做。',lessonId:ls[1].id},
  {title:'第二次引导练习',action:extra[1],expected:ls[1].guidedPractice.steps.at(-1).expected,lessonId:ls[1].id},
  {title:ls[2].title,action:'阅读分步讲解，完成代码示例，再逐项核对练习的预期结果与排错提示。',expected:'把本课机制放回本周的小项目中解释。',lessonId:ls[2].id},
  {title:'组合成一个小实验',action:extra[2],expected:deliverables[w.id],lessonId:ls[2].id},
  {title:'复盘与检查',action:extra[3],expected:'保留做错的解释、修正后的答案与尚未验证的问题。',lessonId:null}
 ].map((d,i)=>({...d,day:i+1,minutes:minutes[i]}));
 return {...w,deliverable:deliverables[w.id],schedule};
}
